-- =============================================================================
-- Certifications : conditions d'examen et labs exigés, et banque de questions Linux de départ.
-- Rejouable : les mises à jour réécrivent les mêmes valeurs ; les questions (identifiants fixes)
-- ne sont insérées qu'une fois. Questions relues dans la revue de code du dépôt.
-- =============================================================================

-- Banques et labs exigés des certifications pour lesquelles des contenus existent déjà.
UPDATE assessment.certifications SET exam_platforms = ARRAY['linux']::platform.os_platform[], exam_question_count = 10, exam_time_limit_s = 1200,
       required_labs = ARRAY['linux-disque-plein-nginx', 'linux-port-80-occupe'] WHERE code = 'LINUX-ADMIN';
UPDATE assessment.certifications SET exam_platforms = ARRAY['network']::platform.os_platform[],
       required_labs = ARRAY['reseau-dns-interne', 'reseau-route-par-defaut'] WHERE code = 'NET-SPEC';
UPDATE assessment.certifications SET exam_platforms = ARRAY['docker']::platform.os_platform[],
       required_labs = ARRAY['docker-variable-renommee', 'docker-port-deja-alloue'] WHERE code = 'DOCKER-SPEC';
UPDATE assessment.certifications SET exam_platforms = ARRAY['security']::platform.os_platform[],
       required_labs = ARRAY['cyber-ssh-force-brute', 'cyber-secrets-lisibles'] WHERE code = 'CYBER-SPEC';
UPDATE assessment.certifications SET exam_platforms = ARRAY['windows']::platform.os_platform[] WHERE code IN ('WIN-TECH', 'WIN-ADMIN');
UPDATE assessment.certifications SET exam_platforms = ARRAY['linux']::platform.os_platform[] WHERE code = 'LINUX-EXPERT';
UPDATE assessment.certifications SET exam_platforms = ARRAY['devops', 'kubernetes']::platform.os_platform[] WHERE code = 'DEVOPS-SPEC';
UPDATE assessment.certifications SET exam_platforms = ARRAY['postgresql']::platform.os_platform[] WHERE code = 'PG-SPEC';
UPDATE assessment.certifications SET exam_platforms = ARRAY['windows', 'linux', 'network']::platform.os_platform[], exam_question_count = 40,
       exam_time_limit_s = 3600 WHERE code = 'SYSMASTER-EXPERT';

-- Banque Linux (examen LINUX-ADMIN : 10 questions tirées au sort).
INSERT INTO assessment.questions (id, type, prompt_md, choices, answer, explanation, difficulty, platform, generated_by_ai, reviewed) VALUES
  ('5405d5bf-df2d-5e83-bf2f-70028c3edf55', 'single', 'Un service ne démarre plus et `df -h` montre `/var` à 100 %. Quelle est la première chose à faire ?', '[{"id": "a", "text": "Identifier ce qui occupe la place avec du -sh /var/*, avant de supprimer quoi que ce soit"}, {"id": "b", "text": "Supprimer tout le contenu de /var/log"}, {"id": "c", "text": "Redémarrer le serveur pour libérer de l''espace"}, {"id": "d", "text": "Agrandir la partition immédiatement"}]'::jsonb, '["a"]'::jsonb, 'On mesure avant d''agir : du montre quel répertoire a grossi. Vider /var/log efface des preuves et peut casser des services ; redémarrer ne libère pas un fichier présent sur disque ; agrandir traite le symptôme sans connaître la cause.', 'intermediate', 'linux', false, true),
  ('e4956b19-1893-5553-856b-8cb55bb92db6', 'single', 'Pourquoi vider un gros journal avec `truncate -s 0 fichier` plutôt que de le supprimer avec `rm` quand un processus l''écrit encore ?', '[{"id": "a", "text": "Parce que rm d''un fichier ouvert ne libère pas l''espace tant que le processus le garde ouvert"}, {"id": "b", "text": "Parce que rm est interdit sur les fichiers de /var/log"}, {"id": "c", "text": "Parce que truncate compresse le fichier"}, {"id": "d", "text": "Il n''y a aucune différence"}]'::jsonb, '["a"]'::jsonb, 'Un fichier supprimé mais encore ouvert reste sur le disque (visible avec lsof +L1) jusqu''à la fermeture. truncate garde le même fichier et libère l''espace tout de suite ; il ne compresse rien.', 'intermediate', 'linux', false, true),
  ('c21e3cdc-1120-55e3-9d46-45a4846dd5f7', 'single', '`systemctl start nginx` échoue et le journal indique « bind() to 0.0.0.0:80 failed (98: Address already in use) ». Quelle commande confirme la cause ?', '[{"id": "a", "text": "ss -tlnp | grep :80"}, {"id": "b", "text": "df -h"}, {"id": "c", "text": "chmod 755 /etc/nginx"}, {"id": "d", "text": "systemctl enable nginx"}]'::jsonb, '["a"]'::jsonb, 'Le message dit qu''un autre processus écoute déjà le port 80 : ss -tlnp montre lequel. df concerne l''espace disque, chmod les droits, et enable ne fait que préparer le démarrage au boot.', 'beginner', 'linux', false, true),
  ('6d9c0f6d-e6a5-5f12-bfca-0a9c26246bed', 'single', 'Quelle est la différence entre `systemctl enable` et `systemctl start` ?', '[{"id": "a", "text": "enable prépare le démarrage automatique au boot, start lance le service maintenant"}, {"id": "b", "text": "Ce sont deux synonymes"}, {"id": "c", "text": "enable lance le service maintenant et au boot"}, {"id": "d", "text": "start rend le démarrage permanent"}]'::jsonb, '["a"]'::jsonb, 'enable crée les liens qui feront démarrer le service au prochain boot, sans le lancer ; start le lance tout de suite sans rien rendre permanent. enable --now combine les deux.', 'beginner', 'linux', false, true),
  ('9080f81b-bce5-5a7d-afec-d1851a685421', 'multiple', 'Un fichier `.env` contenant un mot de passe est en mode 644, propriétaire root, groupe www-data. L''application tourne sous www-data. Cochez toutes les affirmations justes.', '[{"id": "a", "text": "Tous les comptes du serveur peuvent le lire"}, {"id": "b", "text": "chmod 640 garde la lecture pour www-data et la retire aux autres"}, {"id": "c", "text": "chmod 600 est plus sûr et l''application continuera de fonctionner"}, {"id": "d", "text": "chmod 777 réglerait le problème"}]'::jsonb, '["a", "b"]'::jsonb, '644 donne la lecture aux « autres ». 640 la réserve au propriétaire (root) et au groupe www-data. 600 la retirerait aussi au groupe : l''application ne pourrait plus lire sa configuration. 777 aggraverait tout.', 'intermediate', 'linux', false, true),
  ('151c15b5-7d68-589f-8fbc-59e02d293d99', 'single', 'Dans `ls -l`, que signifie `-rw-r-----` ?', '[{"id": "a", "text": "Le propriétaire lit et écrit, le groupe lit, les autres n''ont aucun droit"}, {"id": "b", "text": "Tout le monde peut lire, seul le propriétaire écrit"}, {"id": "c", "text": "Le fichier est exécutable par le groupe"}, {"id": "d", "text": "Le propriétaire n''a que la lecture"}]'::jsonb, '["a"]'::jsonb, 'Les trois triplets se lisent propriétaire, groupe, autres : rw- (lecture, écriture), r-- (lecture), --- (rien). C''est le mode 640.', 'beginner', 'linux', false, true),
  ('b837630b-bff7-5a9f-a48e-797af5351dc0', 'single', 'Après une migration, `ping 10.0.0.1` répond mais `ping depot.exemple.fr` affiche « Temporary failure in name resolution ». Que regarder en premier ?', '[{"id": "a", "text": "Le serveur DNS configuré dans /etc/resolv.conf"}, {"id": "b", "text": "La table de routage"}, {"id": "c", "text": "Le pare-feu local"}, {"id": "d", "text": "La carte réseau"}]'::jsonb, '["a"]'::jsonb, 'Le réseau fonctionne (une adresse IP répond) : c''est la résolution de noms qui échoue. Le routage, le pare-feu et la carte sont déjà mis hors de cause par le ping réussi vers l''IP.', 'beginner', 'linux', false, true),
  ('e4cf40c9-0105-54cf-9ec9-4fbad462eebf', 'single', 'Pourquoi `journalctl -u nom-du-service` est-il souvent plus utile que `systemctl status` pour comprendre un échec ?', '[{"id": "a", "text": "Il montre l''historique complet des messages du service, pas seulement les dernières lignes"}, {"id": "b", "text": "Il redémarre le service en mode débogage"}, {"id": "c", "text": "Il corrige automatiquement l''erreur"}, {"id": "d", "text": "Il affiche la configuration du service"}]'::jsonb, '["a"]'::jsonb, 'systemctl status résume l''état et quelques lignes ; journalctl -u donne tous les messages du service (avec -n, -f ou --since pour filtrer). Il ne redémarre et ne corrige rien.', 'beginner', 'linux', false, true),
  ('37b3a90b-1e1a-50e3-a12e-9e12fb8a3609', 'single', 'Vous devez modifier une ligne dans un fichier de configuration critique sur un serveur en production. Quelle démarche est la plus sûre ?', '[{"id": "a", "text": "Sauvegarder le fichier, modifier, vérifier la syntaxe (ex. nginx -t), puis recharger le service"}, {"id": "b", "text": "Modifier directement puis redémarrer le serveur"}, {"id": "c", "text": "Supprimer le fichier et laisser le paquet le recréer"}, {"id": "d", "text": "Modifier et attendre le prochain redémarrage planifié"}]'::jsonb, '["a"]'::jsonb, 'Une copie permet de revenir en arrière, la vérification de syntaxe évite de couper le service, et un reload applique sans interruption. Redémarrer tout le serveur ou supprimer la configuration est disproportionné et risqué.', 'intermediate', 'linux', false, true),
  ('b46341b1-0ec2-5108-a1bd-5ce7e6b3e15d', 'multiple', 'Une route par défaut ajoutée avec `ip route add default via 10.0.0.1` répare le réseau. Cochez toutes les affirmations justes.', '[{"id": "a", "text": "Elle sera perdue au prochain redémarrage si elle n''est pas écrite dans la configuration réseau"}, {"id": "b", "text": "Elle est enregistrée automatiquement dans /etc/network/interfaces"}, {"id": "c", "text": "Il faut aussi la déclarer dans la configuration (gateway, netplan…) pour qu''elle dure"}, {"id": "d", "text": "Elle ne prend effet qu''après un redémarrage"}]'::jsonb, '["a", "c"]'::jsonb, 'ip route modifie la table du noyau immédiatement mais en mémoire seulement : rien n''est écrit sur le disque. Pour que la correction survive au redémarrage, elle doit figurer dans la configuration du réseau.', 'intermediate', 'linux', false, true),
  ('ea46bffe-2c6f-52bb-8ec7-b8190662b458', 'single', 'Un utilisateur demande `chmod -R 777 /var/www` « pour que ça marche ». Que répondre ?', '[{"id": "a", "text": "Refuser : chercher quel compte doit accéder à quoi et donner le droit minimal"}, {"id": "b", "text": "Accepter, c''est la solution standard"}, {"id": "c", "text": "Accepter mais seulement la nuit"}, {"id": "d", "text": "Utiliser 666 à la place, c''est équivalent mais plus sûr"}]'::jsonb, '["a"]'::jsonb, '777 donne l''écriture à tous les comptes : n''importe quel processus compromis pourrait modifier le site. On identifie le compte du service (www-data) et on accorde le droit minimal nécessaire.', 'beginner', 'linux', false, true),
  ('0dafd69c-1219-549a-a20c-ae4666e31d41', 'single', 'Quel signal indique qu''un service a été tué faute de mémoire ?', '[{"id": "a", "text": "Un message « Out of memory: Killed process … » dans le journal du noyau (journalctl -k ou dmesg)"}, {"id": "b", "text": "Un code de sortie 0"}, {"id": "c", "text": "Un fichier core dans /etc"}, {"id": "d", "text": "Le service apparaît « enabled »"}]'::jsonb, '["a"]'::jsonb, 'L''OOM killer du noyau journalise le processus qu''il termine. Un code 0 signifie une fin normale ; « enabled » ne concerne que le démarrage au boot.', 'intermediate', 'linux', false, true)
ON CONFLICT (id) DO NOTHING;
